#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
long long low=1e18,best=0;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);
low=min(low,x);best=max(best,x-low);}
printf("%lld\n",best);return 0;}

